import{_ as o,C as r,o as s,c as n,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const v=JSON.parse('{"title":"Live view of a run","description":"Watch the page each worker of a running CI run, or of a run a developer shares from their machine, is on, from the run page, in a project that turns it on: a few images a second with the call each was taken at, sent only while someone watches and never stored.","frontmatter":{"title":"Live view of a run","description":"Watch the page each worker of a running CI run, or of a run a developer shares from their machine, is on, from the run page, in a project that turns it on: a few images a second with the call each was taken at, sent only while someone watches and never stored.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/live-view.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/live-view.html"}],["meta",{"property":"og:title","content":"Live view of a run | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Watch the page each worker of a running CI run, or of a run a developer shares from their machine, is on, from the run page, in a project that turns it on: a few images a second with the call each was taken at, sent only while someone watches and never stored."}]]},"headers":[],"relativePath":"features/live-view.md","filePath":"features/live-view.md","lastUpdated":1793450333000}'),l={name:"features/live-view.md"};function c(p,e,u,w,g,f){const a=r("Needs");return s(),n("div",null,[e[0]||(e[0]=t("h1",{id:"live-view-of-a-run",tabindex:"-1"},[i("Live view of a run "),t("a",{class:"header-anchor",href:"#live-view-of-a-run","aria-label":'Permalink to "Live view of a run"'},"​")],-1)),h(a,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p>In a project that turns the live view on, a running test of a CI run, or of a run a developer <a href="#share-a-run-from-your-machine">shares from their machine</a>, gets <strong>Watch</strong> on its run page: it opens the page that worker is on, a few images a second, each with the call it was taken at. It is for a CI run that seems stuck, or a teammate&#39;s paused test, without waiting for the trace. Nothing you do in the view reaches the test.</p><h2 id="where-to-watch-a-run" tabindex="-1">Where to watch a run <a class="header-anchor" href="#where-to-watch-a-run" aria-label="Permalink to &quot;Where to watch a run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>The run</th><th>Where its test&#39;s page shows</th></tr></thead><tbody><tr><td>A CI run, or a run shared from a developer&#39;s machine</td><td>Its page on the team instance: <strong>Watch</strong></td></tr><tr><td>A run you start from VS Code, a JetBrains IDE or a terminal</td><td>Its browser when headed; at a stop, Piwi Picker&#39;s <a href="./runs-window.html#watch-live">Runs window</a> and the editor&#39;s <a href="./editor-run-control.html#a-headless-run">paused page</a></td></tr><tr><td>A run the desktop app starts</td><td>Its <a href="./desktop-runs.html#watch-live">Local runs</a> tray and the Runs window, at a stop</td></tr></tbody></table><p>A stop is a breakpoint, a <code>page.pause()</code> or <strong>Pause</strong>. A run that reports to the desktop app gets no <strong>Watch</strong>: the app hands out no live view key.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>The live view is off in every project. A Project admin turns it on in <strong>Project → Settings → Live view</strong>. It applies to each CI run that starts after, as the reporter&#39;s global setup registers it: <a href="/guide/reporter.html"><code>wrapConfig</code></a> adds that setup. A CI job is told by its provider&#39;s variable (<code>GITHUB_ACTIONS</code>, <code>GITLAB_CI</code>, …) or by <code>CI</code> set to anything but <code>false</code> or <code>0</code>. Such a run&#39;s log then says:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Piwi Dashboard] Live view on: people who may open this run can watch its tests&#39; pages on the dashboard while it runs. Nothing is stored.</span></span></code></pre></div><p>A CI run without a view logs why instead.</p><p>Turning it off ends every view at once; a run that started while it was off stays without one.</p><h2 id="check-availability" tabindex="-1">Check availability <a class="header-anchor" href="#check-availability" aria-label="Permalink to &quot;Check availability&quot;">​</a></h2><p>A running run&#39;s <strong>Tests</strong> tab says <strong>Live view available</strong>, or what is missing, its help giving the step:</p><table tabindex="0"><thead><tr><th>It says</th><th>Why, and what to do</th></tr></thead><tbody><tr><td><strong>Live view off</strong></td><td>A Project admin turns it on for the next runs.</td></tr><tr><td><strong>Live view unavailable</strong></td><td>The run has no key: it started before the setting was on, without <code>wrapConfig</code>&#39;s global setup, with <code>streaming</code> off, or before the instance restarted. Start a new run.</td></tr><tr><td><strong>Live view waiting</strong></td><td>No worker is connected yet: they are starting.</td></tr><tr><td><strong>No worker connected</strong></td><td>Tests run without one: the specs import <code>test</code> from <code>@playwright/test</code>, not the <a href="/guide/capture-fixtures.html">capture fixtures</a>.</td></tr><tr><td><strong>Not shared live</strong></td><td>The run is on a developer&#39;s machine: they <a href="#share-a-run-from-your-machine">share it</a>.</td></tr></tbody></table><h2 id="watch-a-worker" tabindex="-1">Watch a worker <a class="header-anchor" href="#watch-a-worker" aria-label="Permalink to &quot;Watch a worker&quot;">​</a></h2><p>On the run page&#39;s <strong>Tests</strong> tab, <strong>Watch</strong> beside a running test opens its worker&#39;s view: the test&#39;s page as the browser paints it, headless or not, and under it the call the image was taken at (<code>Click getByRole(&#39;button&#39;, { name: &#39;Pay&#39; }) · checkout.spec.ts:30</code>). A still page sends no new image.</p><p>In a CI run, the view also follows that call: how long it has run, Playwright&#39;s log of it as a failed call&#39;s error prints it, and while it waits, what its locator matches (no element yet, several, or one not enabled), outlined on the image, with the point a click acts on. A shared run shows the call alone.</p><p>A view belongs to the test whose row opened it. Opened between two tests or in a <code>beforeAll</code>, it says so and shows the next test&#39;s page. It ends with its test, its worker or the run, when the live view is turned off, or when you close it.</p><p>A CI run never stops at a breakpoint or a <code>page.pause()</code>; a shared run does, and its row then says <strong>Paused</strong> at the stopped call, which opens in your editor.</p><h2 id="share-a-run-from-your-machine" tabindex="-1">Share a run from your machine <a class="header-anchor" href="#share-a-run-from-your-machine" aria-label="Permalink to &quot;Share a run from your machine&quot;">​</a></h2><p>Choose <strong>Share live</strong> while a local run executes to let a teammate watch it. The run must report to a team instance whose project enables live view, and connect to an editor or the desktop app for controls.</p><table tabindex="0"><thead><tr><th>Where</th><th>Share</th><th>Stop</th></tr></thead><tbody><tr><td>VS Code</td><td><strong>Piwi: Share the run live on the team instance</strong>, or the status bar&#39;s broadcast icon</td><td><strong>Piwi: Stop sharing the run live</strong>, or the status bar&#39;s <strong>Live</strong></td></tr><tr><td>JetBrains IDEs</td><td><strong>Tools → Piwi → Share the Run Live</strong></td><td><strong>Tools → Piwi → Stop Sharing the Run Live</strong></td></tr><tr><td>Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a></td><td><strong>Share live</strong> under the run&#39;s name</td><td><strong>Stop sharing</strong></td></tr><tr><td>The desktop app&#39;s <a href="./desktop-runs.html">Local runs tray</a></td><td><strong>Share live</strong> above the run&#39;s workers</td><td><strong>Stop sharing</strong></td></tr></tbody></table><p>The first share in a window asks for confirmation. The shared run shows its destination, viewer count and a link to copy.</p><p>Until then, its workers send nothing, and its running tests say <strong>Not shared live</strong> where <strong>Watch</strong> would be. Once shared, its stops (the call, its file and line, the test&#39;s title) reach everyone with the run&#39;s page open, and images only those watching. <strong>Stop sharing</strong> closes the views within seconds and clears <strong>Paused</strong> from the rows. Closing the editor or the desktop app stops it too.</p><p>A run that cannot be shared says why: it reports to no instance or to the desktop app, its project has the live view off, or the reporter&#39;s global setup did not register it. A sharing that stops on its own says why (the live view turned off, the instance restarted or stopped answering), and <strong>Share live</strong> shows again.</p><h2 id="what-is-sent-to-whom-and-what-is-kept" tabindex="-1">What is sent, to whom, and what is kept <a class="header-anchor" href="#what-is-sent-to-whom-and-what-is-kept" aria-label="Permalink to &quot;What is sent, to whom, and what is kept&quot;">​</a></h2><ul><li><strong>Nothing from a run on your machine until you share it.</strong> Its workers open no connection.</li><li><strong>Nothing while nobody watches.</strong> Each worker of a CI or shared run keeps one connection to the dashboard and says only when its test stops and goes on. No image is taken.</li><li><strong>While someone watches a worker</strong>, that worker sends JPEG images of its test&#39;s page, at most 640 by 400 pixels at quality 50, four a second at most and about 256 KB a second: a heavier image holds the next one back longer. A test whose trace or video already films the page shares that recording&#39;s images, 800 pixels wide at quality 90, and so sends fewer of them. The recording stays whole. A test that starts its own <code>page.screencast</code> gets it, and the view goes on with an image a second. A CI run&#39;s worker also sends the call&#39;s log. Nothing of the view is a step of the test or an action of its trace.</li><li><strong>Only to people who may open the run</strong>: watching needs what opening the run needs, the project&#39;s <a href="/operate/project-access.html">roles</a>. On an instance with authentication off, that is anyone who can reach it.</li><li><strong>Nothing is kept.</strong> The dashboard relays each image to the people watching that worker and drops it: never written to the database, the logs or an export. A viewer that reads slowly gets the latest image alone. The run&#39;s trace stays the record.</li></ul><p><strong>Masked in the worker</strong>, with <code>@piwitests/reporter</code> 0.64.0 or later (an older one masks nothing): before an image leaves it, the worker paints over password fields, fields whose <code>autocomplete</code> asks for a one-time code or a card&#39;s number or code, and the project&#39;s <strong>Masked elements</strong> (Playwright locators). While one shows, two images a second go at most. A secret in the page&#39;s own text still shows; the caption and the log hide credentials and typed text. The workers reach the dashboard with a key the run got as it registered: it opens this run&#39;s live view and nothing else, ends with the run, and is never in the environment of the tests, their hooks or their fixtures, so a process they start does not get it.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Watch only.</strong> No input and no controls: a test is stepped from the <a href="./editor-run-control.html">editor</a> or the <a href="./runs-window.html">Runs window</a>.</li><li><strong>The test&#39;s <code>page</code>.</strong> The view shows the page of Playwright&#39;s <code>page</code> fixture; a popup or a second page is not shown.</li><li><strong>Sixteen views of a run at a time</strong>, four of them one person&#39;s with authentication on: a fifth closes that person&#39;s oldest.</li><li><strong>One dashboard server.</strong> The view is relayed in the memory of one server, as the run&#39;s live events are, so it needs a deployment of one server (<a href="/operate/deployment.html#resource-requirements">Resource requirements</a>). Sticky sessions do not make up for it: the run&#39;s setup, its CI workers and the people watching are separate clients.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: the worker side of the view</li><li><a href="./runs-window.html">Runs window</a>: the live view of a test your editor runs, with its controls, and Share live</li><li><a href="./desktop-runs.html">Desktop app runs</a>: the desktop app&#39;s runs, and Share live from its tray</li><li><a href="./evidence.html">Failure evidence</a>: what a finished test keeps</li></ul>',30))])}const y=o(l,[["render",c]]);export{v as __pageData,y as default};
